styles.css:
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;700&family=JetBrains+Mono:wght@400;500;700&family=Inter:wght@400;500;600&family=Raleway:wght@400;500;600;700;900&display=swap');
/* Shared Gravity design system. Content and navigation remain in their original pages. */ :root {
  color-scheme: light;
  --bg:#f7fafc;
  --text:#101116;
  --muted:#4e5262;
  --subtle:#747a8f;
  --accent:#0e2ac5;
  --accent-bright:#2f69ff;
  --accent-text:#fff;
  --line:rgba(14,42,197,.13);
  --line-bright:rgba(14,42,197,.3);
  --panel:rgba(255,255,255,.42);
  --panel-hover:rgba(255,255,255,.64);
  --accent-soft:rgba(14,42,197,.07);
  --header-bg:rgba(246,248,255,.78);
  --shadow:0 14px 40px -12px rgba(14,42,197,.14);
  --serifless:'Raleway',sans-serif;
  --body:'Raleway',sans-serif;
  --mono:'JetBrains Mono',monospace;
  --wordmark:'Space Grotesk',sans-serif;
  --ease:cubic-bezier(.16,1,.3,1);
  --page:calc(100% - 96px);
  --radius:24px;
  --reading-surface:rgba(255,255,255,.68);
}
* {
  box-sizing:border-box
}
html,body {
  margin:0;
  padding:0;
  width:100%
}
html {
  scroll-padding-top:112px;
  scroll-behavior:auto
}
body {
  min-width:320px;
  overflow-x:hidden;
  background:var(--bg);
  color:var(--text);
  font-family:var(--body);
  font-weight:500;
  line-height:1.65;
  -webkit-font-smoothing:antialiased;
  isolation:isolate
}
body::before {
  content:'';
  position:fixed;
  inset:0;
  z-index:-3;
  pointer-events:none;
  background:radial-gradient(circle at center,#fff 0%,#ecefff 35%,#c2d1ff 100%)
}
a {
  color:inherit;
  text-decoration:none
}
button,input {
  font:inherit;
  color:inherit
}
button {
  cursor:pointer
}
button,a {
  -webkit-tap-highlight-color:transparent
}
img {
  display:block;
  max-width:100%
}
h1,h2,h3,p {
  margin:0
}
h1,h2,h3 {
  font-family:var(--serifless);
  font-weight:500;
  letter-spacing:-.045em
}
h1 {
  font-size:clamp(54px,6.6vw,104px);
  line-height:1
}
h2 {
  font-size:clamp(40px,5.3vw,80px);
  line-height:1.02
}
h3 {
  font-size:24px;
  line-height:1.2
}
h1 em,h2 em {
  font-style:normal;
  color:var(--accent)
}
::selection {
  background:var(--accent);
  color:white
}
:focus-visible {
  outline:2px solid var(--accent);
  outline-offset:5px
}
[hidden] {
  display:none!important
}
svg {
  width:18px;
  height:18px;
  fill:none;
  stroke:currentColor;
  stroke-width:1.6;
  stroke-linecap:round;
  stroke-linejoin:round;
  flex-shrink:0
}
::-webkit-scrollbar {
  width:8px
}
::-webkit-scrollbar-track {
  background:transparent
}
::-webkit-scrollbar-thumb {
  background:rgba(14,42,197,.18);
  border-radius:99px
}
::-webkit-scrollbar-thumb:hover {
  background:rgba(14,42,197,.32)
}
.skip-link {
  position:fixed;
  left:16px;
  top:12px;
  z-index:120;
  padding:10px 18px;
  border-radius:99px;
  background:white;
  color:var(--accent);
  transform:translateY(-180%)
}
.skip-link:focus {
  transform:none
}
.gravity-background {
  position:fixed;
  inset:0;
  z-index:-2;
  pointer-events:none;
  background:radial-gradient(circle at center,#fff 0%,#ecefff 35%,#c2d1ff 100%)
}
.gravity-background::before,.gravity-background::after {
  content:'';
  position:absolute;
  inset:0;
  opacity:0;
  transition:opacity 1.2s cubic-bezier(.65,0,.35,1)
}
.gravity-background::before {
  background:radial-gradient(circle at center,#fff 0%,#fbffe5 38%,#e8ff9c 100%)
}
.gravity-background::after {
  background:radial-gradient(circle at center,#fff 0%,#fff0f1 38%,#ffd1d5 100%)
}
.gravity-background[data-stage='1']::before {
  opacity:1
}
.gravity-background[data-stage='2']::after {
  opacity:1
}
.site-header {
  position:fixed;
  inset:0 0 auto;
  z-index:50;
  height:96px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:24px;
  padding:0 48px;
  transition:background .4s,box-shadow .4s,backdrop-filter .4s
}
.site-header.is-scrolled {
  background:var(--header-bg);
  backdrop-filter:blur(24px);
  box-shadow:0 1px 0 #ffffff88
}
.brand {
  display:flex;
  align-items:center;
  gap:12px;
  flex-shrink:0
}
.brand-mark {
  display:grid;
  place-items:center;
  width:40px;
  height:40px;
  flex-shrink:0;
  color:#fff;
  background:url('./brand-gear.svg') center / contain no-repeat;
  filter:drop-shadow(0 4px 7px #0e2ac526);
  font:500 12px var(--wordmark);
  letter-spacing:.04em
}
.brand-copy {
  display:grid;
  line-height:1.2
}
.brand-copy strong {
  font:700 18px var(--wordmark);
  letter-spacing:.16em;
  text-transform:uppercase
}
.brand-copy small {
  font:8px var(--mono);
  color:var(--subtle);
  letter-spacing:.05em;
  margin-top:6px
}
.header-controls {
  display:flex;
  align-items:center;
  gap:28px
}
.nav-links {
  display:flex;
  align-items:center;
  gap:38px
}
.nav-links a {
  font-size:14px;
  font-weight:500;
  position:relative;
  transition:opacity .2s
}
.nav-links a:hover {
  opacity:.55
}
.nav-links .is-active::after {
  content:'';
  position:absolute;
  bottom:-8px;
  left:50%;
  width:4px;
  height:4px;
  background:var(--accent);
  border-radius:50%
}
.nav-links a:last-child {
  padding:10px 18px;
  border:1px solid #ffffffbb;
  border-radius:99px;
  background:#ffffff30;
  box-shadow:inset 0 1.5px 2px #ffffffb3,0 8px 30px #0000000a;
  backdrop-filter:blur(24px)
}
.theme-toggle,.menu-toggle {
  width:44px;
  height:44px;
  display:grid;
  place-items:center;
  border-radius:50%;
  border:1px solid #ffffff66;
  background:#ffffff33;
  box-shadow:inset 0 1.5px 2px #ffffffb3,0 8px 30px #0000000a;
  backdrop-filter:blur(24px)
}
.theme-toggle:hover,.menu-toggle:hover {
  background:#ffffff70
}
.theme-toggle svg {
  width:24px;
  height:24px;
  color:#52617b;
  stroke-width:2.8
}
.palette-ring-dot {
  fill:currentColor;
  stroke:none;
  opacity:0;
  transition:opacity .2s
}
:root[data-theme="dark"] .theme-toggle .palette-ring-dot {
  opacity:1
}
.menu-toggle {
  display:none
}
.menu-toggle span {
  display:block;
  width:17px;
  height:1px;
  background:currentColor;
  position:absolute;
  transition:transform .2s
}
.menu-toggle span:first-child {
  transform:translateY(-3px)
}
.menu-toggle span:last-child {
  transform:translateY(3px)
}
.menu-toggle[aria-expanded=true] span:first-child {
  transform:rotate(45deg)
}
.menu-toggle[aria-expanded=true] span:last-child {
  transform:rotate(-45deg)
}
main,.site-footer {
  position:relative;
  z-index:2
}
.hero {
  position:relative;
  min-height:100svh;
  display:flex;
  align-items:flex-end;
  padding:140px 48px 70px
}
.hero-atmosphere {
  position:fixed;
  inset:0;
  pointer-events:none;
  z-index:-1
}
.hero-atmosphere canvas {
  width:100%;
  height:100%;
  display:block
}
.model-fallback {
  position:absolute;
  inset:10% 12% 34%;
  border-radius:50%;
  background:radial-gradient(circle at 42% 30%,#fff9 0%,#a8c1ff66 24%,#2f69ff33 43%,transparent 68%);
  filter:blur(15px)
}
.hero-copy {
  position:relative;
  width:100%;
  z-index:1
}
.hero-copy>.eyebrow {
  margin-bottom:22px
}
.eyebrow {
  font:500 11px/1.8 var(--mono);
  letter-spacing:.15em;
  text-transform:uppercase;
  color:var(--accent)
}
.status-dot {
  display:inline-block;
  width:6px;
  height:6px;
  border-radius:50%;
  background:var(--accent);
  margin-right:10px;
  box-shadow:0 0 10px #2f69ff55
}
.hero-row {
  display:grid;
  grid-template-columns:minmax(0,1fr) minmax(260px,380px);
  gap:40px;
  align-items:end
}
.hero-row-name {
  font-size:clamp(90px,10vw,160px);
  line-height:.98;
  letter-spacing:-.065em;
  font-weight:500
}
.hero-row-name br {
  display:none
}
.hero-row-headline {
  font-size:clamp(25px,2.6vw,40px);
  line-height:1.08;
  letter-spacing:-.035em;
  font-weight:500;
  max-width:400px
}
.hero-3d-cluster {
  display:none
}
.hero-support {
  display:grid;
  grid-template-columns:minmax(0,650px) minmax(280px,380px);
  align-items:center;
  justify-content:space-between;
  gap:clamp(24px,3vw,44px);
  margin-top:30px
}
.hero-text {
  font-size:15px;
  line-height:1.6;
  color:var(--muted);
  max-width:650px
}
.hero-actions,.contact-links,.card-actions {
  display:flex;
  gap:12px;
  align-items:center;
  flex-wrap:wrap
}
.button {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:18px;
  min-height:44px;
  padding:11px 22px;
  border:1px solid #ffffffc9;
  border-radius:99px;
  background:#ffffff40;
  backdrop-filter:blur(18px);
  box-shadow:inset 0 1.5px 2px #ffffffb3,0 8px 30px #00000008;
  font-size:13px;
  font-weight:500;
  transition:transform .3s,background .3s
}
.button:hover {
  transform:translateY(-2px);
  background:#ffffffa6
}
.button.primary {
  color:white;
  background:var(--accent);
  border-color:var(--accent);
  box-shadow:inset 0 1px 2px #ffffff55,0 8px 22px #0e2ac51a
}
.button.primary:hover {
  background:#173ada
}
.button span {
  font-size:17px
}
.hero-facts {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:clamp(16px,3vw,48px);
  margin:28px 0 0;
  padding-top:20px;
  border-top:1px solid #0e2ac51a
}
.hero-facts div {
  display:flex;
  align-items:baseline;
  gap:12px
}
.hero-facts dt {
  font:10px/1.6 var(--mono);
  color:var(--muted);
  letter-spacing:.1em;
  text-transform:uppercase
}
.hero-facts dd {
  font-size:12px;
  margin:0;
  color:var(--muted)
}
.scroll-cue {
  position:absolute;
  right:48px;
  bottom:24px;
  display:flex;
  gap:12px;
  align-items:center;
  font:10px/1.6 var(--mono);
  text-transform:uppercase;
  letter-spacing:.15em;
  color:var(--subtle)
}
.scroll-cue span {
  animation:scroll-pulse 2s infinite
}
.hero-pop {
  transition:opacity 1s var(--ease),transform 1s var(--ease),filter 1s var(--ease)
}
.field-loading .hero-pop {
  opacity:0;
  transform:translateY(22px);
  filter:blur(5px)
}
.field-ready .hero-pop {
  opacity:1;
  transform:none;
  filter:none;
  transition-delay:calc(var(--pop,0) * .08s)
}
.section {
  position:relative;
  min-height:100svh;
  padding:150px 48px;
  display:flex;
  flex-direction:column;
  justify-content:center;
  gap:40px
}
.section-kicker {
  display:flex;
  gap:16px;
  align-items:center;
  font:10px var(--mono);
  letter-spacing:.2em;
  color:var(--accent);
  text-transform:uppercase
}
.section-kicker::before {
  content:'['
}
.section-kicker::after {
  content:']'
}
.section-kicker span {
  color:#0e2ac580
}
.overview-grid {
  display:grid;
  grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);
  gap:clamp(32px,5vw,72px);
  align-items:start
}
.overview-grid h2 {
  max-width:750px
}
.overview-copy {
  padding:28px;
  border-radius:24px;
  background:var(--reading-surface);
  border:1px solid #ffffff9c;
  backdrop-filter:blur(18px);
  box-shadow:var(--shadow);
  font-size:17px;
  line-height:1.8;
  color:var(--muted)
}
.overview-copy p+p {
  margin-top:20px
}
.overview-copy p a {
  color:var(--accent);
  text-decoration:underline;
  text-underline-offset:4px
}
.text-link {
  display:inline-flex;
  align-items:center;
  gap:18px;
  margin-top:24px;
  font-size:13px;
  color:var(--accent)
}
.split-heading {
  display:grid;
  grid-template-columns:minmax(0,1.2fr) minmax(0,.8fr);
  gap:clamp(32px,5vw,72px);
  align-items:end
}
.split-heading>p {
  max-width:440px;
  font-size:17px;
  line-height:1.7;
  color:var(--muted)
}
.experience-section {
  padding-top:140px;
  padding-bottom:140px
}
.experience-intro h2 {
  max-width:830px
}
.experience-list {
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:20px;
  margin-top:14px
}
.experience-card {
  position:relative;
  padding:30px;
  border:1px solid #ffffffb3;
  border-radius:24px;
  background:var(--reading-surface);
  backdrop-filter:blur(24px);
  box-shadow:var(--shadow);
  transition:transform .4s var(--ease)
}
.experience-card:hover {
  transform:translateY(-4px)
}
.experience-rail {
  display:none
}
.experience-meta {
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:12px;
  flex-wrap:wrap;
  padding-bottom:22px;
  border-bottom:1px solid #0e2ac512
}
.experience-date {
  display:flex;
  gap:8px;
  flex-wrap:wrap;
  font:11px/1.6 var(--mono);
  color:var(--muted)
}
.experience-status {
  display:flex;
  align-items:center;
  gap:7px;
  font:10px/1.6 var(--mono);
  text-transform:uppercase;
  letter-spacing:.08em;
  color:var(--accent)
}
.experience-status>span {
  height:5px;
  width:5px;
  border-radius:50%;
  background:var(--accent);
  box-shadow:0 0 8px #2f69ff88
}
.experience-status-complete {
  color:var(--subtle)
}
.experience-heading {
  display:flex;
  justify-content:space-between;
  align-items:start;
  flex-wrap:wrap;
  gap:12px;
  margin-top:24px
}
.experience-role {
  font:11px/1.7 var(--mono);
  letter-spacing:.07em;
  text-transform:uppercase;
  color:var(--muted);
  margin-bottom:8px
}
.experience-heading h3 {
  font-size:38px
}
.experience-heading h3 span {
  display:inline-block;
  font-size:22px;
  color:var(--accent);
  transition:transform .25s
}
.experience-heading a:hover span {
  transform:translate(3px,-3px)
}
.experience-institution {
  max-width:none;
  font-size:12px;
  color:var(--muted);
  text-align:left
}
.experience-description {
  font-size:15px;
  color:var(--muted);
  line-height:1.75;
  margin:20px 0 24px
}
.tag-list {
  display:flex;
  gap:7px;
  flex-wrap:wrap
}
.tag {
  display:inline-block;
  padding:6px 10px;
  border:1px solid #ffffff8c;
  border-radius:99px;
  background:#ffffff40;
  color:var(--muted);
  font:11px/1.6 var(--mono);
  max-width:100%;
  overflow-wrap:anywhere
}
.tech-grid {
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));
  align-items:stretch;
  gap:16px;
  margin-top:20px
}
.tech-card {
  position:relative;
  min-width:0;
  border-radius:24px;
  padding:28px 24px;
  border:1px solid #ffffffb3;
  background:var(--reading-surface);
  backdrop-filter:blur(20px);
  box-shadow:var(--shadow)
}
.tech-card-index {
  display:block;
  font:10px var(--mono);
  letter-spacing:.2em;
  color:var(--accent);
  margin-bottom:24px
}
.tech-card h3 {
  font-size:24px;
  min-height:2.4em;
  margin-bottom:22px
}
.tech-card .tag-list {
  gap:8px
}
.tech-card .tag {
  font-size:11px;
  background:#ffffff66
}
.contact-section {
  min-height:80svh;
  padding:128px 48px 112px;
  background:#0a0a0a;
  color:#fff;
  border-radius:64px 64px 0 0;
  overflow:hidden
}
.contact-section::before {
  content:'';
  position:absolute;
  inset:0;
  pointer-events:none;
  background:radial-gradient(ellipse at 80% 25%,#2f69ff38,transparent 45%),radial-gradient(ellipse at 10% 95%,#5175ff22,transparent 45%)
}
.contact-card {
  position:relative;
  max-width:960px;
  margin:0 auto;
  text-align:center
}
.contact-card .eyebrow {
  color:#ffffff66;
  margin-bottom:24px
}
.contact-card h2 {
  font-size:clamp(60px,8vw,120px)
}
.contact-card>p:not(.eyebrow) {
  max-width:620px;
  margin:28px auto 36px;
  font-size:18px;
  line-height:1.7;
  color:#ffffff99
}
.contact-links {
  justify-content:center;
  gap:16px
}
.contact-links .button {
  gap:7px;
  padding-inline:18px;
  min-height:48px;
  min-width:150px;
  border-color:#ffffff26;
  background:#ffffff0d;
  box-shadow:none
}
.contact-links .contact-icon {
  width:16px;
  height:16px;
  color:#fff;
}
.contact-links .contact-icon-solid {
  fill:currentColor;
  stroke:none;
}
.contact-links .button:hover {
  background:#ffffff1a
}
.contact-links .button.primary {
  gap:5px;
  background:#0e2ac5;
  border-color:#0e2ac5
}
.site-footer {
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:24px;
  padding:32px 48px;
  background:#0a0a0a;
  color:#ffffff66;
  border-top:1px solid #ffffff1a;
  font:10px/1.6 var(--mono)
}
.site-footer>a {
  color:#ffffffb3
}
.site-footer>a:hover {
  color:#fff
}
.site-footer>p:first-child {
  color:white;
  font:700 13px var(--wordmark);
  letter-spacing:.06em
}
/* Work, archive and long-form notes share the same pearl/glass system. */ .page-shell {
  width:var(--page);
  max-width:1600px;
  margin:0 auto;
  min-height:calc(100svh - 96px);
  padding:176px 0 100px
}
.page-hero {
  display:grid;
  grid-template-columns:1.35fr .65fr;
  gap:7vw;
  align-items:end;
  padding:30px 0 96px
}
.page-hero .eyebrow {
  margin-bottom:26px
}
.page-hero h1 {
  max-width:1000px;
  font-size:clamp(54px,6.3vw,96px)
}
.page-intro {
  font-size:16px;
  line-height:1.8;
  color:var(--muted);
  max-width:440px
}
.work-index {
  display:grid;
  grid-template-columns:minmax(0,1.05fr) minmax(0,.8fr) minmax(0,1fr);
  gap:32px;
  padding:20px 28px;
  font:9px var(--mono);
  letter-spacing:.2em;
  color:var(--subtle);
  border-top:1px solid var(--line)
}
.project-showcase-grid {
  display:grid;
  gap:24px
}
.project-showcase-card {
  display:grid;
  grid-template-columns:minmax(0,1.05fr) minmax(0,.8fr) minmax(0,1fr);
  gap:32px;
  align-items:start;
  border-radius:28px;
  border:1px solid #ffffffaa;
  background:#ffffff55;
  padding:28px;
  box-shadow:var(--shadow);
  backdrop-filter:blur(24px)
}
.project-visual {
  position:relative;
  display:grid;
  place-items:center;
  width:100%;
  aspect-ratio:4/3;
  padding:0;
  min-width:0;
  overflow:hidden;
  border:0;
  border-radius:18px;
  background:radial-gradient(circle at 32% 30%,#fff,#b8d2ff 50%,#4979ee);
  color:#0e2ac5
}
.project-visual img {
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  object-fit:contain;
  transition:transform .6s var(--ease)
}
.project-visual:hover img {
  transform:scale(1.04)
}
.project-visual.cyan {
  background:radial-gradient(circle at 30% 30%,#fff,#c9f1ff,#96e5ff)
}
.project-visual.violet {
