.reveal {
  opacity:1
}
.reveal-pending {
  opacity:0;
  transform:translateY(42px);
  filter:blur(8px);
  transition:opacity 1.5s var(--ease),transform 1.5s var(--ease),filter 1.5s var(--ease)
}
.reveal-pending.is-visible {
  opacity:1;
  transform:none;
  filter:none
}
/* Keep skill text sharp while retaining the existing entrance fade and slide. */
.tech-card.reveal-pending {
  filter:none;
  transition:opacity 1.5s var(--ease),transform 1.5s var(--ease);
}
.field-loader {
  position:fixed;
  inset:0;
  z-index:100;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:26px;
  background:radial-gradient(circle at 50% 42%,#fff 0%,#eef2ff 45%,#dbe4ff 100%);
  transition:opacity .55s cubic-bezier(.65,0,.35,1)
}
.field-loader.leaving {
  opacity:0;
  pointer-events:none
}
.field-loader>* {
  animation:loader-in .8s var(--ease) both
}
.field-loader-status {
  font:10px var(--mono);
  letter-spacing:.28em;
  text-transform:uppercase;
  color:#6b7bb5;
  animation-delay:.1s!important
}
.field-loader-track {
  width:clamp(180px,32vw,280px);
  height:2px;
  border-radius:99px;
  background:#0e2ac524;
  animation-delay:.26s!important
}
.field-loader-fill {
  height:100%;
  width:0;
  border-radius:inherit;
  background:linear-gradient(90deg,#5175ff,#0e2ac5);
  box-shadow:0 0 14px #2f69ff88;
  transition:width .45s var(--ease)
}
.field-loader-counter {
  font:700 11px var(--mono);
  letter-spacing:.1em;
  font-variant-numeric:tabular-nums;
  color:var(--accent);
  animation-delay:.42s!important
}
@keyframes loader-in {
  from {
    opacity:0;
    transform:translateY(18px);
    filter:blur(6px)
  }
  to {
    opacity:1;
    transform:none;
    filter:none
  }
}
@keyframes scroll-pulse {
  50% {
    opacity:.4;
    transform:translateY(4px)
  }
}
