.hero-copy,.overview-grid>.section-heading,.experience-intro,.skills-section>.section-heading {
  position:relative;
  isolation:isolate;
}
.hero-copy::before,.overview-grid>.section-heading::before,.experience-intro::before,.skills-section>.section-heading::before {
  content:'';
  position:absolute;
