};

const palette = getDynamicColors(ballColor);

// Scroll-driven palettes: hero (base) → volt-lime (drop) → rose-pink (heart).
const palHero = palette;
const palLime = getDynamicColors('#E1FC03');
const palPink = getDynamicColors('#FFC5C2');
